import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, mix, step, color, float, sub, add, mul, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  // ----- Helpers -----
  const toColor = (hex) => new Color(hex);
  const createPlaneMaterial = () => {
    const material = new MeshStandardNodeMaterial();
    material.metalness = 0.2;
    material.roughness = 0.6;
    material.clearcoat = 0.1;
    material.transparent = true;
    material.depthWrite = true;

    // Gradient (vertical)
    const topColor = color(toColor('#1a1a22'));
    const bottomColor = color(toColor('#111116'));
    const grad = mix(topColor, bottomColor, uv().y);

    // Border
    const borderThickness = 0.006; // world units
    const panelWidth = 3.4;
    const panelHeight = 1.9;
    const borderU = borderThickness / panelWidth;
    const borderV = borderThickness / panelHeight;
    const bw = float(Math.min(borderU, borderV));

    const uvNode = uv();
    const maskX = step(bw, uvNode.x);
    const maskX2 = step(bw, sub(float(1), uvNode.x));
    const maskY = step(bw, uvNode.y);
    const maskY2 = step(bw, sub(float(1), uvNode.y));
    const inner = mul(mul(maskX, maskX2), mul(maskY, maskY2));
    const borderMask = sub(float(1), inner);
    const borderColor = color(toColor('#26262f'));

    const finalColor = mix(grad, borderColor, borderMask);
    material.colorNode = finalColor;
    return material;
  };

  // ----- Panel -----
  const panelGroup = new Group();
  const panelGeom = new PlaneGeometry(3.4, 1.9);
  const panelMat = createPlaneMaterial();
  const panelMesh = new Mesh(panelGeom, panelMat);
  panelGroup.add(panelMesh);

  // ----- Text -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Quote mark
  const quoteMarkItem = items.find((i) => i.role === 'quote-mark');
  const quoteMark = quoteMarkItem
    ? ctx.fontAtlas.createText(quoteMarkItem.text, {
        fontSize: quoteMarkItem.typography?.fontSize ?? 62,
        color: '#ff2a38',
        align: 'left',
      })
    : null;
  if (quoteMark) {
    quoteMark.position.set(-1.7 + 0.5, 0.95 - 0.5, 0);
    panelGroup.add(quoteMark);
  }

  // Quote text
  const quoteItem = items.find((i) => i.role === 'quote');
  const quoteText = quoteItem
    ? ctx.fontAtlas.createText(quoteItem.text, {
        fontSize: quoteItem.typography?.fontSize ?? 20,
        color: '#e8ecf2',
        align: 'left',
        maxWidthPx: 2400,
      })
    : null;
  if (quoteText) {
    const baseY = quoteMark ? -0.25 : 0.45 - 0.25;
    quoteText.position.set(-1.7 + 0.5, baseY, 0.03);
    panelGroup.add(quoteText);
  }

  // Attribution
  const attributionItem = items.find((i) => i.role === 'attribution');
  const attributionText = attributionItem
    ? ctx.fontAtlas.createText(attributionItem.text, {
        fontSize: attributionItem.typography?.fontSize ?? 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0.08,
      })
    : null;
  if (attributionText) {
    const baseY = quoteText ? quoteText.position.y - 0.25 : -0.05;
    attributionText.position.set(-1.7 + 0.5, baseY, 0);
    panelGroup.add(attributionText);
  }

  // Accent rule (emissive line)
  const accentGeom = new PlaneGeometry(0.2, 0.02);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.emissive = toColor('#ff2a38');
  accentMat.emissiveIntensity = 1.4;
  accentMat.transparent = true;
  accentMat.metalness = 0;
  accentMat.roughness = 1;
  const accentMesh = new Mesh(accentGeom, accentMat);
  const accentY = attributionText ? attributionText.position.y - 0.12 : -0.06;
  accentMesh.position.set(-1.7 + 0.5, accentY, 0);
  panelGroup.add(accentMesh);

  // ----- Animations -----
  const timelines = [];

  // Fade-up for whole panel
  const fadeTimeline = gsap.timeline();
  fadeTimeline.from(panelGroup, {
    opacity: 0,
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  timelines.push(fadeTimeline);

  // Weighted-settle for quote mark
  if (quoteMark) {
    const settleTimeline = gsap.timeline();
    settleTimeline.from(quoteMark.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    });
    timelines.push(settleTimeline);
  }

  // ----- Cleanup -----
  panelGroup.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    panelGeom.dispose();
    panelMat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
    if (quoteMark) quoteMark.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
    if (quoteText) quoteText.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
    if (attributionText) attributionText.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  // No interaction handlers required
  panelGroup.userData.handlers = {};

  return panelGroup;
}
